const raw = $input.first().json.choices[0].message.content;
const cleaned = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (err) {
  return [{ json: { _valid: false, _raw: cleaned, _error: err.message } }];
}
return [{ json: { _valid: true, generation_run_id: $('Reshape Data').first().json.generation_run_id, agent: 'seo', seo_output: parsed } }];

const allItems = $input.all();
if (allItems.length === 0 || !allItems[0].json.agent) {
  return [{ json: { _e: 1, _msg: 'No approved Stage 1 data found. Run Stage 1 first and approve it.' } }];
}
const items = $input.all();
const positioning = items.find(i => i.json.agent === 'positioning');
const icp = items.find(i => i.json.agent === 'icp');
const marketingStage = items.find(i => i.json.marketing_stage)?.json.marketing_stage || 'Brand Awareness (Top of Funnel)';
return [{
  json: {
    _e: 0,
    generation_run_id: $('Webhook').first().json.body.generation_run_id,
    company_name: $('Webhook').first().json.body.company_name || '',
    marketing_stage: marketingStage,
    positioning_output: positioning ? positioning.json.output : null,
    icp_output: icp ? icp.json.output : null
  }
}];

const data = $('Reshape Data').first().json;

const messagingBody = {
  model: 'deepseek/deepseek-v4-flash',
  temperature: 0.2,
  top_p: 0.1,
  response_format: { type: 'json_object' },
  provider: { order: ['Together', 'AtlasCloud', 'Venice'], allow_fallbacks: true },
  messages: [
    {
      role: 'system',
      content: 'You are an elite B2B messaging strategist. Output ONLY valid JSON. SCHEMA: {"hero_headline":"string","subheadline_value_prop":"string","core_messaging_pillars":[{"pillar_title":"string","supporting_copy":"string"}],"conversion_hook":"string"}'
    },
