    }
  ]
};

const gtmBody = {
  model: 'deepseek/deepseek-v4-flash',
  temperature: 0.2,
  top_p: 0.1,
  response_format: { type: 'json_object' },
  provider: { order: ['Together', 'AtlasCloud', 'Venice'], allow_fallbacks: true },
  messages: [
    {
      role: 'system',
      content: 'You are an elite B2B go-to-market strategist. Output ONLY valid JSON. SCHEMA: {"primary_distribution_channels":["string"],"launch_sequencing_playbook":"string","growth_loops_identified":["string"],"initial_30_day_milestones":["string"]}'
    },
    {
      role: 'user',
      content: 'Generate GTM strategy for this company only. Company: ' + data.positioning_output.category_definition + ' Positioning: ' + data.positioning_output.positioning_statement + ' Persona: ' + data.icp_output.primary_target_persona + ' Buying triggers: ' + JSON.stringify(data.icp_output.buying_triggers) + ' Return JSON with primary_distribution_channels, launch_sequencing_playbook, growth_loops_identified, initial_30_day_milestones.'
    }
  ]
};

const seoBody = {
  model: 'deepseek/deepseek-v4-flash',
  temperature: 0.2,
  top_p: 0.1,
  response_format: { type: 'json_object' },
  provider: { order: ['Together', 'AtlasCloud', 'Venice'], allow_fallbacks: true },
  messages: [
    {
      role: 'system',
      content: 'You are an elite B2B SEO strategist. Output ONLY valid JSON. SCHEMA: {"topical_authority_clusters":[{"core_pillar":"string","sub_topics":["string"]}],"aeo_citation_strategy":"string","high_intent_search_queries":["string"]}'
    },
    {
      role: 'user',
      content: 'Generate SEO strategy for this company only. Company: ' + data.positioning_output.category_definition + ' Positioning: ' + data.positioning_output.positioning_statement + ' Persona: ' + data.icp_output.primary_target_persona + ' Return JSON with topical_authority_clusters, aeo_citation_strategy, high_intent_search_queries.'
    }
  ]
};

return [{
  json: {
    generation_run_id: data.generation_run_id,
    messaging_body: messagingBody,
    gtm_body: gtmBody,
    seo_body: seoBody
  }
}];

const data = $('Reshape Data').first().json;
const serperResults = $(' Serper ').first().json;
const marketingStage = data.marketing_stage || 'Brand Awareness (Top of Funnel)';

// Extract top organic results from Serper
const organic = serperResults.organic || [];
const serpContext = organic.slice(0, 5).map((r, i) => 
  `${i+1}. ${r.title} — ${r.snippet}`
).join('\n');

// Set funnel guidance based on marketing stage
let funnelGuidance = '';
if (marketingStage.includes('Brand Awareness')) {
  funnelGuidance = 'Focus on TOP OF FUNNEL queries: educational content, problem-awareness searches, broad category terms, "what is" and "how to" queries. Avoid bottom-funnel conversion terms.';
} else if (marketingStage.includes('Mid Funnel') || marketingStage.includes('Lead Generation')) {
  funnelGuidance = 'Focus on MID FUNNEL queries: comparison searches, alternative searches, solution-aware terms, "best X for Y" queries, competitor comparisons.';
} else if (marketingStage.includes('Conversion') || marketingStage.includes('Bottom')) {
  funnelGuidance = 'Focus on BOTTOM OF FUNNEL queries: high-intent purchase terms, "buy X", "X pricing", "X vs Y", free trial searches, demo request queries.';
}

const seoBody = {
  model: 'deepseek/deepseek-v4-flash',
  temperature: 0.2,
  top_p: 0.1,
  response_format: { type: 'json_object' },
  provider: { order: ['Together', 'AtlasCloud', 'Venice'], allow_fallbacks: true },
  messages: [
    {
      role: 'system',
      content: 'You are an elite B2B SEO strategist. Output ONLY valid JSON. SCHEMA: {"topical_authority_clusters":[{"core_pillar":"string","sub_topics":["string"]}],"aeo_citation_strategy":"string","high_intent_search_queries":["string"]}'
    },
    {
      role: 'user',
      content: 'Generate SEO strategy for this company only. Company: ' + data.positioning_output.category_definition + ' Positioning: ' + data.positioning_output.positioning_statement + ' Persona: ' + data.icp_output.primary_target_persona + ' Marketing stage: ' + marketingStage + '\n\nFUNNEL GUIDANCE: ' + funnelGuidance + '\n\nReal Google SERP data for this market:\n' + serpContext + '\n\nUse this real search data to identify actual queries and content gaps. Match all queries and clusters to the funnel stage specified. Return JSON with topical_authority_clusters, aeo_citation_strategy, high_intent_search_queries.'
    }
  ]
};

return [{ json: { seo_body: seoBody } }];

const data = $('Merge Stage 2').first()?.json || {};
const stage1 = $('Reshape Data').first()?.json || {};

const escapeHTML = (str) => {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
};

const positioning = stage1.positioning_output || {};
const icp = stage1.icp_output || {};
const messaging = data.messaging_output || {};
const gtm = data.gtm_output || {};
const seo = data.seo_output || {};

const companyName = escapeHTML(stage1.company_name || data.company_name || stage1.positioning_output?.company_name || 'Company');
const marketingStage = escapeHTML(stage1.marketing_stage || data.marketing_stage || 'Brand Awareness (Top of Funnel)');

// ── Parse 3 stat fields from persona string
// The ICP prompt explicitly forces "age range (e.g. 28-45)", "company size", "seniority level"
// so these patterns are reliable against this specific prompt's output format
const personaRaw = icp.primary_target_persona || '';

const ageMatch = personaRaw.match(/age\s*(?:range)?\s*[:\s]?\s*(\d{2}\s*[-–]\s*\d{2}|\d{2}\+)/i);
const ageRange = ageMatch ? ageMatch[1].replace(/\s/g, '') : '28–45';

const sizeMatch = personaRaw.match(/company\s*size\s*[:\s]+([^,;.\n]+)/i);
const companySize = sizeMatch ? sizeMatch[1].trim().replace(/employees?/i, '').trim() + ' employees' : 'SMB–Mid-market';

const seniorityMatch = personaRaw.match(/seniority\s*(?:level)?\s*[:\s]+([^,;.\n]+)/i);
const seniority = seniorityMatch ? seniorityMatch[1].trim() : 'IC / Team Lead';

// ── Positioning pillars
const pillars = (positioning.differentiation_pillars || []);
const pillarsHTML = pillars.map((p, i) => `
  <div class="pillar-card">
    <div class="pillar-num">${String(i + 1).padStart(2, '0')}</div>
    <div class="pillar-text">${escapeHTML(p)}</div>
  </div>
`).join('');

// ── ICP triggers — numbered cards only, no invented scores
const triggers = (icp.buying_triggers || []);
const triggersHTML = triggers.map((t, i) => `
  <div class="trigger-card">
    <div class="trigger-index">${i + 1}</div>
    <div class="trigger-text">${escapeHTML(t)}</div>
  </div>`
).join('');

const fears = (icp.customer_fears_and_risks || []);
const fearsHTML = fears.map(f =>
  `<li class="fear-item"><span class="fear-dot">▸</span>${escapeHTML(f)}</li>`
).join('');

// ── Messaging pillars
const messagingPillars = (messaging.core_messaging_pillars || []).map((p, i) => `
  <div class="msg-pillar">
    <div class="msg-pillar-header">
      <span class="msg-pillar-num">${String(i + 1).padStart(2, '0')}</span>
      <span class="msg-pillar-title">${escapeHTML(p.pillar_title)}</span>
    </div>
    <p class="msg-pillar-body">${escapeHTML(p.supporting_copy)}</p>
  </div>
`).join('');

// ── GTM
const channels = (gtm.primary_distribution_channels || []);
const channelsHTML = channels.map(c => `<div class="channel-chip">${escapeHTML(c)}</div>`).join('');

const milestones = (gtm.initial_30_day_milestones || []).slice(0, 4);
const milestonesHTML = milestones.map((m, i) => {
  const labels = ['Day 7', 'Day 14', 'Day 21', 'Day 30'];
  return `
    <div class="milestone-block">
      <div class="milestone-marker"></div>
      <div class="milestone-label">${labels[i] || `Week ${i + 1}`}</div>
      <div class="milestone-text">${escapeHTML(m)}</div>
    </div>`;
}).join('');

const loops = (gtm.growth_loops_identified || []).slice(0, 3);
const loopsHTML = loops.map(l =>
  `<div class="loop-card"><div class="loop-icon">↺</div><div class="loop-text">${escapeHTML(l)}</div></div>`
).join('');

// ── GTM funnel SVG — clean fixed layout
const CARD_W = 134;
const CARD_H = 112;
const GAP = 24;
const TOTAL_W = 4 * CARD_W + 3 * GAP;
const SVG_H = CARD_H + 90;
const midY = 30 + CARD_H / 2;

const funnelStages = [
  { label: 'STAGE 1', title: 'Awareness',   bg: '#1a1a2e', titleColor: 'white',   subColor: 'rgba(255,255,255,0.55)', items: ['Outbound email', 'LinkedIn sequences', 'SEO content'] },
  { label: 'STAGE 2', title: 'Acquisition', bg: '#0f4c3a', titleColor: 'white',   subColor: 'rgba(255,255,255,0.65)', items: ['Free tier sign-up', 'PLG onboarding', 'CRM integrations'] },
  { label: 'STAGE 3', title: 'Activation',  bg: '#00a67e', titleColor: 'white',   subColor: 'rgba(255,255,255,0.82)', items: ['First summary sent', '3 calls recorded', 'Team invite sent'] },
  { label: 'STAGE 4', title: 'Retention',   bg: '#00c9a7', titleColor: '#1a1a2e', subColor: 'rgba(26,26,46,0.62)',   items: ['Viral team sharing', 'Company rollout', 'Analytics upsell'] }
];

const funnelSVGParts = funnelStages.map((s, i) => {
  const x = i * (CARD_W + GAP);
  const cardY = 30;
  const cx = x + CARD_W / 2;

  const dividerColor = s.title === 'Retention' ? 'rgba(26,26,46,0.12)' : 'rgba(255,255,255,0.1)';
  const itemY = cardY + 52;

  const itemLines = s.items.map((item, ii) =>
    `<text x="${cx}" y="${itemY + ii * 16}" text-anchor="middle" style="font-family:'Helvetica Neue',Arial,sans-serif;font-size:9px;fill:${s.subColor};">${escapeHTML(item)}</text>`
  ).join('');

  const arrow = i < 3 ? `<line x1="${x + CARD_W + 4}" y1="${midY}" x2="${x + CARD_W + GAP - 5}" y2="${midY}" stroke="#d1d5db" stroke-width="1.5" marker-end="url(#arw)"/>` : '';

  return `
    <text x="${cx}" y="18" text-anchor="middle" style="font-family:'Helvetica Neue',Arial,sans-serif;font-size:7.5px;font-weight:700;fill:#9ca3af;letter-spacing:1.5px;">${s.label}</text>
    <rect x="${x}" y="${cardY}" width="${CARD_W}" height="${CARD_H}" rx="6" fill="${s.bg}"/>
    <text x="${cx}" y="${cardY + 22}" text-anchor="middle" style="font-family:'Helvetica Neue',Arial,sans-serif;font-size:12px;font-weight:800;fill:${s.titleColor};">${s.title}</text>
    <line x1="${x + 16}" y1="${cardY + 31}" x2="${x + CARD_W - 16}" y2="${cardY + 31}" stroke="${dividerColor}" stroke-width="1"/>
    ${itemLines}
    ${arrow}`;
}).join('');

// Loop arc below cards
const arcY1 = 30 + CARD_H + 6;
const arcYMid = arcY1 + 26;
const arcX1 = 3 * (CARD_W + GAP) + CARD_W / 2;
const arcX2 = CARD_W / 2;

const gtmFunnelSVG = `<svg viewBox="0 0 ${TOTAL_W} ${SVG_H}" xmlns="http://www.w3.org/2000/svg" width="${TOTAL_W}" height="${SVG_H}" style="max-width:100%;display:block;">
  <defs>
    <marker id="arw" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0,0 L0,6 L6,3 z" fill="#d1d5db"/></marker>
    <marker id="arw-teal" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L0,8 L8,4 z" fill="#00c9a7"/></marker>
  </defs>
  ${funnelSVGParts}
  <path d="M ${arcX1},${arcY1} Q ${arcX1},${arcYMid} ${(arcX1+arcX2)/2},${arcYMid} Q ${arcX2},${arcYMid} ${arcX2},${arcY1}"
    fill="none" stroke="#00c9a7" stroke-width="1.5" stroke-dasharray="4,3" marker-end="url(#arw-teal)"/>
  <text x="${(arcX1+arcX2)/2}" y="${arcYMid + 14}" text-anchor="middle"
    style="font-family:'Helvetica Neue',Arial,sans-serif;font-size:8.5px;fill:#00a67e;font-weight:600;">↺ Viral loop: shared recording → new sign-up → team adoption</text>
</svg>`;

// ── SEO intent badges — inferred from query structure, no invented numbers
const intentBadge = (q) => {
  const l = q.toLowerCase();
  if (/\bvs\b|compare|alternative|best .* for|top .* tool/.test(l)) return { label: 'Comparison',    bg: '#fef3c7', color: '#92400e' };
  if (/how to|what is|why |guide|tips|learn/.test(l))               return { label: 'Informational', bg: '#eff6ff', color: '#1e40af' };
  if (/pricing|free|cost|plan|sign up|download|get started/.test(l)) return { label: 'Transactional', bg: '#f0fdf4', color: '#166534' };
  if (/\b(fathom|notion|loom|otter|fireflies|read ai|fellow)\b/.test(l)) return { label: 'Navigational', bg: '#fdf4ff', color: '#7e22ce' };
  return { label: 'High Intent', bg: '#e6faf6', color: '#0d7a60' };
};

const seoQueries = (seo.high_intent_search_queries || []);
const seoQueriesHTML = seoQueries.map((q, i) => {
  const badge = intentBadge(q);
  return `
  <div class="query-row">
    <span class="query-rank">${String(i + 1).padStart(2, '0')}</span>
    <span class="query-text">${escapeHTML(q)}</span>
    <span class="intent-badge" style="background:${badge.bg};color:${badge.color};">${badge.label}</span>
  </div>`;
}).join('');

const seoClusters = (seo.topical_authority_clusters || []).map(c => `
  <div class="seo-cluster">
    <div class="seo-cluster-title">${escapeHTML(c.core_pillar)}</div>
    <div class="seo-tags">${(c.sub_topics || []).map(s => `<span class="seo-tag">${escapeHTML(s)}</span>`).join('')}</div>
  </div>
`).join('');

const date = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });

const stageColorMap = { 'brand awareness': '#7c5cbf', 'lead generation': '#00a67e', 'conversion': '#d4720c', 'retention': '#1a6fb5' };
const stageLower = marketingStage.toLowerCase();
let stageBg = '#4a5568';
for (const [k, v] of Object.entries(stageColorMap)) { if (stageLower.includes(k)) { stageBg = v; break; } }

// ── Section icons
const iconPositioning = `<svg width="28" height="28" viewBox="0 0 32 32" fill="none"><circle cx="16" cy="16" r="14" stroke="#00c9a7" stroke-width="2"/><circle cx="16" cy="16" r="8" stroke="#00c9a7" stroke-width="1.5" stroke-dasharray="3 2"/><circle cx="16" cy="16" r="2.5" fill="#00c9a7"/><line x1="16" y1="2" x2="16" y2="7" stroke="#00c9a7" stroke-width="2" stroke-linecap="round"/><line x1="16" y1="25" x2="16" y2="30" stroke="#00c9a7" stroke-width="2" stroke-linecap="round"/><line x1="2" y1="16" x2="7" y2="16" stroke="#00c9a7" stroke-width="2" stroke-linecap="round"/><line x1="25" y1="16" x2="30" y2="16" stroke="#00c9a7" stroke-width="2" stroke-linecap="round"/></svg>`;
const iconICP = `<svg width="28" height="28" viewBox="0 0 32 32" fill="none"><circle cx="16" cy="11" r="5.5" stroke="#00c9a7" stroke-width="2"/><path d="M5 27c0-6.075 4.925-11 11-11s11 4.925 11 11" stroke="#00c9a7" stroke-width="2" stroke-linecap="round"/><path d="M23 14l2 2 4-4" stroke="#00c9a7" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const iconMessaging = `<svg width="28" height="28" viewBox="0 0 32 32" fill="none"><rect x="3" y="5" width="22" height="15" rx="3" stroke="#00c9a7" stroke-width="2"/><path d="M3 17l6 6v-6" stroke="#00c9a7" stroke-width="2" stroke-linejoin="round"/><line x1="8" y1="10" x2="20" y2="10" stroke="#00c9a7" stroke-width="1.8" stroke-linecap="round"/><line x1="8" y1="14" x2="16" y2="14" stroke="#00c9a7" stroke-width="1.8" stroke-linecap="round"/></svg>`;
const iconGTM = `<svg width="28" height="28" viewBox="0 0 32 32" fill="none"><path d="M8 6L16 3L24 6L27 14L16 20L5 14Z" stroke="#00c9a7" stroke-width="1.8" stroke-linejoin="round"/><circle cx="16" cy="11" r="2.5" fill="#00c9a7"/><path d="M16 20L16 28" stroke="#00c9a7" stroke-width="2" stroke-linecap="round"/><path d="M12 25l4 3 4-3" stroke="#00c9a7" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const iconSEO = `<svg width="28" height="28" viewBox="0 0 32 32" fill="none"><circle cx="14" cy="14" r="9" stroke="#00c9a7" stroke-width="2"/><line x1="21" y1="21" x2="28" y2="28" stroke="#00c9a7" stroke-width="2.5" stroke-linecap="round"/><line x1="10" y1="14" x2="18" y2="14" stroke="#00c9a7" stroke-width="1.8" stroke-linecap="round"/><line x1="14" y1="10" x2="14" y2="18" stroke="#00c9a7" stroke-width="1.8" stroke-linecap="round"/></svg>`;

const html = `<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { font-family: Georgia, 'Times New Roman', serif; color: #1a1a2e; background: white; font-size: 13px; line-height: 1.6; }

  /* ── COVER — table layout for reliable PDF rendering ── */
 .cover { background: #1a1a2e; color: white; width: 100%; height: 1122px; page-break-after: always; border-left: 6px solid #00c9a7; position: relative; }
  .cover-teal-bar { display: none; }
  .cover-geo-1 { display: none; }
  .cover-geo-2 { display: none; }
  .cover-geo-3 { display: none; }
  .cover-geo-4 { display: none; }
  .cover-brand { padding: 32px 60px 0 66px; display: flex; align-items: center; gap: 12px; }
  .cover-brand-logo { width: 30px; height: 30px; background: #00c9a7; border-radius: 6px; display: inline-flex; align-items: center; justify-content: center; font-family: 'Helvetica Neue', Arial, sans-serif; font-weight: 900; font-size: 13px; color: #1a1a2e; }
  .cover-brand-name { font-family: 'Helvetica Neue', Arial, sans-serif; font-size: 11px; font-weight: 700; letter-spacing: 3px; text-transform: uppercase; color: rgba(255,255,255,0.4); }
  .cover-main { padding: 320px 60px 80px 72px; }
  .cover-report-type { font-family: 'Helvetica Neue', Arial, sans-serif; font-size: 10px; font-weight: 700; letter-spacing: 4px; text-transform: uppercase; color: #00c9a7; margin-bottom: 16px; }
  .cover-company { font-family: 'Helvetica Neue', Arial, sans-serif; font-size: 68px; font-weight: 800; line-height: 1; color: white; margin-bottom: 14px; letter-spacing: -3px; }
  .cover-subtitle { font-family: Georgia, serif; font-size: 20px; color: rgba(255,255,255,0.45); font-style: italic; margin-bottom: 32px; }
  .cover-stage-badge { display: inline-flex; align-items: center; gap: 8px; padding: 8px 18px; background: ${stageBg}; border-radius: 4px; font-family: 'Helvetica Neue', Arial, sans-serif; font-size: 11px; font-weight: 600; color: white; }
  .cover-stage-dot { width: 6px; height: 6px; border-radius: 50%; background: rgba(255,255,255,0.7); display: inline-block; }
.cover-toc { padding: 20px 60px 20px 72px; border-top: 1px solid rgba(255,255,255,0.08); display: flex; position: absolute; bottom: 60px; left: 0; right: 0; }
  .cover-toc-item { flex: 1; padding: 0 16px; border-left: 1px solid rgba(255,255,255,0.07); }
